// Break Slicer: a drum instrument that plays chopped sampled breaks (Amen, Think...) step by step.
// Jungle needs the break itself, cut into hits and re-sequenced: synthesized kits can't fake it.
//
// Break data comes from a LOCAL, gitignored module (breakdata.local.js, generated by a bake script
// from audio you own a copy of): { <name>: { tempo, sr, slices: [[start, end, class], ...], pcm: base64 int16 } }.
// Without it the instrument is silent and says so in its label; nothing sampled is ever tracked in git.
//
// Lanes are hits. Each lane plays ONE slice of the break, chosen by a param (kickSlice = 1, snareSlice = 3...),
// so a step grid re-sequences the break. 'rsnare' plays its slice reversed (the jungle swell).
// pitch: semitones applied by playback rate, so a 137 BPM Amen at +4.1 st sits at 174 BPM: the classic
// pitched-up jungle sound, not a time-stretch. Mono choke: every new hit fades the previous one out fast,
// the way a sampler chopping one break behaves.

import { BaseInstrument } from './base.js';
import { defineInstrument } from './registry.js';

let BREAKS = {};
try { BREAKS = (await import('./breakdata.local.js')).default ?? {}; } catch { /* no local breaks: silent */ }
const NAMES = Object.keys(BREAKS);

const pcmCache = new WeakMap(); // ctx -> { name -> {fwd: AudioBuffer, rev: AudioBuffer} }
function buffers(ctx, name) {
  let m = pcmCache.get(ctx); if (!m) { m = {}; pcmCache.set(ctx, m); }
  if (m[name]) return m[name];
  const b = BREAKS[name]; if (!b) return null;
  const bin = typeof atob === 'function' ? atob(b.pcm) : Buffer.from(b.pcm, 'base64').toString('binary');
  const n = bin.length >> 1;
  const fwd = ctx.createBuffer(1, n, b.sr), rev = ctx.createBuffer(1, n, b.sr);
  const f = fwd.getChannelData(0), r = rev.getChannelData(0);
  for (let i = 0; i < n; i++) { let v = bin.charCodeAt(2 * i) | (bin.charCodeAt(2 * i + 1) << 8); if (v & 0x8000) v -= 0x10000; f[i] = v / 32768; }
  for (let i = 0; i < n; i++) r[i] = f[n - 1 - i];
  return (m[name] = { fwd, rev, n });
}

const LANES = [
  { id: 'kick', label: 'Kick' }, { id: 'kick2', label: 'Kick 2' },
  { id: 'snare', label: 'Snare' }, { id: 'snare2', label: 'Snare 2' },
  { id: 'ghost', label: 'Ghost' }, { id: 'ghost2', label: 'Ghost 2' },
  { id: 'hat', label: 'Hat' }, { id: 'ride', label: 'Ride/Crash' },
  { id: 'rsnare', label: 'Rev Snare' },
  // s1..s32: slice N of the break, by number. Slices are the break's own 8th notes, so stepping s1, s2, s3...
  // every 2 sixteenths plays the break straight; reorder them to chop it.
  ...Array.from({ length: 32 }, (_, i) => ({ id: `s${i + 1}`, label: `Slice ${i + 1}` })),
];
const sliceOf = (laneId, params) => /^s\d+$/.test(laneId) ? +laneId.slice(1) : Math.round(params[`${laneId}Slice`] ?? 1);

class BreakSlicer extends BaseInstrument {
  constructor(ctx, params, def) { super(ctx, params, def); this.last = null; }
  trigger(laneId, time, vel = 1) {
    const name = this.params.break; const b = BREAKS[name]; if (!b || !vel) return;
    const bufs = buffers(this.ctx, name); if (!bufs) return;
    const idx = Math.max(1, Math.min(b.slices.length, sliceOf(laneId, this.params)));
    let [s0, s1] = b.slices[idx - 1];
    const lenMul = this.params[`${laneId}Len`] ?? 1; // play part of the slice (1) or run on into the next ones (>1)
    s1 = Math.min(bufs.n, s0 + Math.round((s1 - s0) * lenMul));
    const reverse = laneId === 'rsnare';
    // kick slices: numbered lanes whose slice the bake classed 'kick' take kickTune too, so EVERY kick (named lane
    // or s-lane) can be pulled back toward the break's original pitch
    const isKickSlice = /^s\d+$/.test(laneId) && b.slices[idx - 1][2] === 'kick';
    const laneTune = isKickSlice ? (this.params.sliceKickTune ?? 0) : (this.params[`${laneId}Tune`] ?? 0);
    const rate = Math.pow(2, ((this.params.pitch ?? 0) + laneTune) / 12);
    const src = this.ctx.createBufferSource();
    src.buffer = reverse ? bufs.rev : bufs.fwd; src.playbackRate.value = rate;
    const g = this.ctx.createGain();
    const durSec = (s1 - s0) / b.sr / rate;
    const lvl = vel * (this.params[`${laneId}Level`] ?? 1);
    g.gain.setValueAtTime(0, time); g.gain.linearRampToValueAtTime(lvl, time + 0.002);
    const tailAt = Math.max(time + 0.004, time + durSec - 0.006);
    g.gain.setValueAtTime(lvl, tailAt); g.gain.linearRampToValueAtTime(0, time + durSec);
    src.connect(g).connect(this.output);
    const offset = reverse ? (bufs.n - s1) / b.sr : s0 / b.sr;
    src.start(time, offset, (s1 - s0) / b.sr);
    if (this.params.choke && this.last && this.last.end > time) { // mono choke: fade the previous hit
      try { this.last.g.gain.cancelScheduledValues(time); this.last.g.gain.setTargetAtTime(0, time, 0.003); this.last.src.stop(time + 0.03); } catch {}
    }
    this.last = { src, g, end: time + durSec };
  }
  allOff() { try { this.last?.src.stop(); } catch {} this.last = null; }
}

const sliceKnob = (lane, label, def) => ({ key: `${lane}Slice`, label: `${label} slice`, type: 'knob', min: 1, max: 32, step: 1, default: def, group: 'Slices' });
const lenKnob = (lane, label) => ({ key: `${lane}Len`, label: `${label} length`, type: 'knob', min: 0.25, max: 4, step: 0.25, default: 1, group: 'Lengths' });
// Per-lane tune/level for the named hit lanes. Tune adds to the global pitch: a kick at tune -pitch plays at the
// break's ORIGINAL pitch while the rest of the break stays pitched up (pitched-up kicks go thin and cartoonish).
const NAMED = ['kick', 'kick2', 'snare', 'snare2', 'ghost', 'ghost2', 'hat', 'ride', 'rsnare'];
const tuneKnob = lane => ({ key: `${lane}Tune`, label: `${lane} tune`, type: 'knob', min: -12, max: 12, step: 0.01, default: 0, unit: 'st', group: 'Tune' });
const levelKnob = lane => ({ key: `${lane}Level`, label: `${lane} level`, type: 'knob', min: 0, max: 2, default: 1, group: 'Levels' });
defineInstrument({
  type: 'breakslicer', label: NAMES.length ? 'Break Slicer' : 'Break Slicer (no local breaks)', kind: 'drums', klass: BreakSlicer,
  lanes: LANES,
  params: [
    { key: 'break', label: 'Break', type: 'select', options: NAMES.map(n => ({ value: n, label: n })), default: NAMES[0] ?? '', group: 'Break' },
    { key: 'pitch', label: 'Pitch', type: 'knob', min: -12, max: 12, step: 0.01, default: 0, unit: 'st', group: 'Break' },
    { key: 'choke', label: 'Choke', type: 'select', options: [{ value: 1, label: 'On' }, { value: 0, label: 'Off' }], default: 1, group: 'Break' },
    sliceKnob('kick', 'Kick', 1), sliceKnob('kick2', 'Kick 2', 10), sliceKnob('snare', 'Snare', 3), sliceKnob('snare2', 'Snare 2', 7),
    sliceKnob('ghost', 'Ghost', 4), sliceKnob('ghost2', 'Ghost 2', 12), sliceKnob('hat', 'Hat', 23), sliceKnob('ride', 'Ride', 31),
    sliceKnob('rsnare', 'Rev Snare', 3),
    ...LANES.filter(l => !/^s\d+$/.test(l.id)).map(l => lenKnob(l.id, l.label)),
    ...NAMED.map(tuneKnob), ...NAMED.map(levelKnob),
    { key: 'sliceKickTune', label: 'Kick slices tune', type: 'knob', min: -12, max: 12, step: 0.01, default: 0, unit: 'st', group: 'Tune' },
    { key: 'level', label: 'Level', type: 'knob', min: 0, max: 1.5, default: 0.9, group: 'Out' },
  ],
  presets: {
    'Amen @174': { break: 'amen', pitch: 4.11 },
    'Think @174': { break: 'think', pitch: 7.55 },
  },
});

export const BREAK_NAMES = NAMES;
export function breakInfo(name) { const b = BREAKS[name]; return b ? { tempo: b.tempo, slices: b.slices.map(([s, e, c], i) => ({ i: i + 1, ms: Math.round((e - s) / b.sr * 1000), class: c })) } : null; }
